#include <iostream>
#include <vector>

/* 把 a 里 lo..mid 和 mid+1..hi 两摊各自排好的数，合起来成从小到大的一摊 */
void join(std::vector<int>& a, int lo, int mid, int hi) {
    std::vector<int> tmp;
    int i = lo;
    int j = mid + 1;

    while (i <= mid && j <= hi) {
        if (a[i] <= a[j]) {
            tmp.push_back(a[i]);
            i++;
        } else {
            tmp.push_back(a[j]);
            j++;
        }
    }
    while (i <= mid) {
        tmp.push_back(a[i]);
        i++;
    }
    while (j <= hi) {
        tmp.push_back(a[j]);
        j++;
    }

    for (int x = 0; x < static_cast<int>(tmp.size()); x++) {
        a[lo + x] = tmp[x];
    }
}

/* 上一课那一招：把 a 里 lo..hi 这一段排成从小到大 */
void sort_half(std::vector<int>& a, int lo, int hi) {
    for (int i = lo; i < hi; i++) {
        for (int j = lo; j < hi - (i - lo); j++) {
            if (a[j] > a[j + 1]) {
                std::swap(a[j], a[j + 1]);
            }
        }
    }
}

int main() {
    int n = 0;
    std::cin >> n;
    std::vector<int> a(n);
    for (int i = 0; i < n; i++) {
        std::cin >> a[i];
    }

    int mid = (n - 1) / 2;
    sort_half(a, 0, mid);
    sort_half(a, mid + 1, n - 1);
    join(a, 0, mid, n - 1);

    std::cout << "合起来：";
    for (int i = 0; i < n; i++) {
        std::cout << a[i] << " ";
    }
    std::cout << "\n";
    return 0;
}

explanationTemplate:
合起来这一招是「**两只手各指一个头，比一比再动手**」喵：

```text
while (i <= mid && j <= hi) {
    if (a[i] <= a[j]) {
        tmp.push_back(a[i]);
        i++;
    } else {
        tmp.push_back(a[j]);
        j++;
    }
}
while (i <= mid) {
    tmp.push_back(a[i]);
    i++;
}
while (j <= hi) {
    tmp.push_back(a[j]);
    j++;
}
for (int x = 0; x < static_cast<int>(tmp.size()); x++) {
    a[lo + x] = tmp[x];
}
```

三处值得多念两遍：

**① `i` 管左边那一摊、`j` 管右边那一摊。** 谁小谁先进 `tmp`，进去的那只手往后挪一格，另一只手不动 —— 这就是「谁小谁先走」。

**② 两个 `while` 一个都不能少。** 前面那一趟比对，是在「有一摊空了」的时候停下来的，可**停不等于搬完**：另一摊剩下的全是大的，得原样搬进去。只写一个的话，另一半的数据得靠运气才刚好对。

**③ 最后要整段搬回去。** `tmp` 只是暂存，`join` 干完活得让 `a` 的 `lo` 到 `hi` 这一段真的变成合好的样子 —— 一个 `for` 把 `tmp` 里的一只只搬回去，别漏。

本喵给你留一句分头记：**谁小谁先走，走完的搬剩的，最后整段搬回家。**
